import{_ as n,o as a,c as p,a3 as l}from"./chunks/framework.bvEHUNtb.js";const r=JSON.parse('{"title":"08 六十四卦基础","description":"从重卦结构、成书脉络与卦变关系建立六十四卦的基础框架。","frontmatter":{"title":"08 六十四卦基础","description":"从重卦结构、成书脉络与卦变关系建立六十四卦的基础框架。","category":"guide","aliases":["六十四卦基础","六十四卦","重卦"]},"headers":[],"relativePath":"topics/traditional-wisdom/symbols/liu-shi-si-gua-basics.md","filePath":"topics/traditional-wisdom/symbols/liu-shi-si-gua-basics.md","lastUpdated":1786982540000}'),e={name:"topics/traditional-wisdom/symbols/liu-shi-si-gua-basics.md"};function t(i,s,c,o,d,u){return a(),p("div",null,[...s[0]||(s[0]=[l(`<h1 id="_08-·-六十四卦基础-从八卦到六十四卦" tabindex="-1">08 · 六十四卦基础：从八卦到六十四卦 <a class="header-anchor" href="#_08-·-六十四卦基础-从八卦到六十四卦" aria-label="Permalink to &quot;08 · 六十四卦基础：从八卦到六十四卦&quot;">​</a></h1><h2 id="版本与引用说明" tabindex="-1">版本与引用说明 <a class="header-anchor" href="#版本与引用说明" aria-label="Permalink to &quot;版本与引用说明&quot;">​</a></h2><p>本篇承担&quot;易经入门详细科普&quot;的职责，因此特别说明：</p><blockquote><p>人更三圣，世历三古的“三圣说”出自班固的《汉书·艺文志》。</p><p>而四圣说实际上是将中古时期的“文王演易”这一项工作，具体分拆为了“文王作卦辞”和“周公作爻辞”，让成书的脉络更加清晰。</p></blockquote><p>《周易》的成书，历史上有一个著名的&quot;四圣&quot;说：</p><blockquote><p>伏羲画卦 → 文王演卦 → 周公作爻辞 → 孔子作十翼</p></blockquote><p>这个说法，流传极广，但<strong>每一环节都有争议</strong>。<br> 本篇将如实呈现：哪些有文献依据，哪些是后世建构，哪些至今存疑。</p><hr><h2 id="一、先说位置-六十四卦在体系中的哪里" tabindex="-1">一、先说位置：六十四卦在体系中的哪里？ <a class="header-anchor" href="#一、先说位置-六十四卦在体系中的哪里" aria-label="Permalink to &quot;一、先说位置：六十四卦在体系中的哪里？&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>道</span></span>
<span class="line"><span> └─ 阴阳</span></span>
<span class="line"><span>      └─ 四象</span></span>
<span class="line"><span>           └─ 八卦（三爻·8种）</span></span>
<span class="line"><span>                ├─ 先天八卦（体）</span></span>
<span class="line"><span>                ├─ 后天八卦（用）</span></span>
<span class="line"><span>                └─ 六十四卦（8×8·64种）← 我们在这里</span></span>
<span class="line"><span>                     = 八卦两两相叠</span></span>
<span class="line"><span>                     = 宇宙所有基本情境的完整枚举</span></span>
<span class="line"><span>                     = 《周易》的符号系统基础</span></span></code></pre></div><p><strong>六十四卦解决的问题：</strong></p><blockquote><p>八卦描述了八种基本状态。<br> 但现实世界的情境，远比八种复杂。<br> 两个基本状态叠加，产生 8×8=64 种组合——<br> 这64种，被认为足以覆盖人世间所有基本情境。</p></blockquote><h2 id="二、从八卦到六十四卦-数学逻辑" tabindex="-1">二、从八卦到六十四卦：数学逻辑 <a class="header-anchor" href="#二、从八卦到六十四卦-数学逻辑" aria-label="Permalink to &quot;二、从八卦到六十四卦：数学逻辑&quot;">​</a></h2><h3 id="_2-1-重卦的生成" tabindex="-1">2.1 重卦的生成 <a class="header-anchor" href="#_2-1-重卦的生成" aria-label="Permalink to &quot;2.1 重卦的生成&quot;">​</a></h3><blockquote><p>【原典】《周易·系辞下传》第二章<br> 【原文】<strong>八卦成列，象在其中矣；因而重之，爻在其中矣。</strong></p></blockquote><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;因而重之&quot;= 将八卦两两叠加</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  上卦（外卦）</span></span>
<span class="line"><span>  ─────────── ← 上面三爻</span></span>
<span class="line"><span>  下卦（内卦）</span></span>
<span class="line"><span>  ─────────── ← 下面三爻</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  8（上卦）× 8（下卦）= 64卦</span></span>
<span class="line"><span>  每卦 6 爻</span></span>
<span class="line"><span>  64 × 6 = 384 爻</span></span></code></pre></div><h3 id="_2-2-三爻到六爻-信息量的跃升" tabindex="-1">2.2 三爻到六爻：信息量的跃升 <a class="header-anchor" href="#_2-2-三爻到六爻-信息量的跃升" aria-label="Permalink to &quot;2.2 三爻到六爻：信息量的跃升&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>三爻八卦：2³ = 8 种状态</span></span>
<span class="line"><span>六爻六十四卦：2⁶ = 64 种状态</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每增加一爻，信息量翻倍：</span></span>
<span class="line"><span>  3爻 → 8</span></span>
<span class="line"><span>  4爻 → 16</span></span>
<span class="line"><span>  5爻 → 32</span></span>
<span class="line"><span>  6爻 → 64</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 六爻，是在三爻基础上，</span></span>
<span class="line"><span>  信息量精确扩展8倍的结果。</span></span></code></pre></div><h3 id="_2-3-重卦-是谁发明的-——考据现状" tabindex="-1">2.3 &quot;重卦&quot;是谁发明的？——考据现状 <a class="header-anchor" href="#_2-3-重卦-是谁发明的-——考据现状" aria-label="Permalink to &quot;2.3 &quot;重卦&quot;是谁发明的？——考据现状&quot;">​</a></h3><p>这是《周易》研究中争议最大的问题之一。</p><p>历史上主要有三种说法：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>说法一：伏羲重卦说</span></span>
<span class="line"><span>  代表人物：郑玄（东汉）</span></span>
<span class="line"><span>  依据：《周礼注》&quot;伏羲制六十四卦&quot;</span></span>
<span class="line"><span>  问题：郑玄之前无此说，先秦文献无据。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>说法二：神农重卦说</span></span>
<span class="line"><span>  代表人物：孙盛（东晋）</span></span>
<span class="line"><span>  依据：《三国志注》引《魏氏春秋》</span></span>
<span class="line"><span>  问题：孤证，无其他文献佐证。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>说法三：文王重卦说</span></span>
<span class="line"><span>  代表人物：王弼（魏晋）</span></span>
<span class="line"><span>  依据：《周易略例》</span></span>
<span class="line"><span>  问题：同样无先秦文献直接支撑。</span></span></code></pre></div><p>梁韦弦《关于数字卦与六十四卦符号体系之形成问题》（《周易研究》，2007年）指出：</p><blockquote><p>从考古材料看，商代甲骨文中已出现六爻数字卦，<br> 说明六十四卦的符号体系<strong>早于文王</strong>已经存在。<br> &quot;文王重卦&quot;之说，在考古证据面前难以成立。</p></blockquote><p>史宁中《从八卦到六十四卦：试论〈周易〉的思维逻辑》（《哲学研究》，2011年）指出：</p><blockquote><p>八卦到六十四卦的演化，是一个<strong>逻辑必然</strong>——<br> 只要掌握了三爻叠加的方法，重卦就是自然的推论，<br> 不需要归功于某一个具体的历史人物。</p></blockquote><p><strong>本篇的处理原则：</strong></p><p>六十四卦符号体系的起源，<strong>早于文王</strong>，具体发明者不可考。<br> 文王的贡献，在于<strong>卦辞的撰写</strong>，而非符号的发明。</p><h2 id="三、《周易》的成书-文王、周公与孔子" tabindex="-1">三、《周易》的成书：文王、周公与孔子 <a class="header-anchor" href="#三、《周易》的成书-文王、周公与孔子" aria-label="Permalink to &quot;三、《周易》的成书：文王、周公与孔子&quot;">​</a></h2><h3 id="_3-1-文王与卦辞" tabindex="-1">3.1 文王与卦辞 <a class="header-anchor" href="#_3-1-文王与卦辞" aria-label="Permalink to &quot;3.1 文王与卦辞&quot;">​</a></h3><blockquote><p>【原典】《史记·太史公自序》，西汉·司马迁<br> 【原文】<strong>昔西伯拘羑里，演《周易》。</strong></p></blockquote><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>西伯 = 周文王姬昌</span></span>
<span class="line"><span>羑（yǒu）里 = 今河南汤阴，商纣王的囚禁之地</span></span>
<span class="line"><span>演《周易》= 推演、整理《周易》</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 司马迁的记载：文王被囚期间，整理推演了《周易》。</span></span></code></pre></div><blockquote><p>【原典】《汉书·艺文志》，东汉·班固<br> 【原文】<strong>文王以诸侯顺命而行道，天人之占可得而效，于是重《易》六爻，作上下篇。&quot;</strong></p></blockquote><p><strong>考据说明：</strong></p><p>&quot;文王作卦辞&quot;这一说法，最早见于东汉马融、郑玄。先秦文献（包括《左传》《国语》中大量引《易》之处）均未明确说&quot;卦辞为文王所作&quot;。</p><p>廖名春《周易经传与易学史新论》（齐鲁书社，2001年），写到：</p><blockquote><p>现代学者普遍认为，卦辞的写定，大约在西周初期（约公元前1046年前后），作者可能是周初史官群体，文王参与其中的可能性存在，但无法确证。</p></blockquote><h3 id="_3-2-周公与爻辞" tabindex="-1">3.2 周公与爻辞 <a class="header-anchor" href="#_3-2-周公与爻辞" aria-label="Permalink to &quot;3.2 周公与爻辞&quot;">​</a></h3><p>传统说法：爻辞为周公所作。</p><p>依据：东汉马融《周易注》</p><p>考据现状：</p><blockquote><p>爻辞中有若干内容涉及文王之后的史事，如&quot;帝乙归妹&quot;（归妹卦）等，说明爻辞的写定，可能跨越文王、周公两个时代，甚至延续到西周中期。</p><pre><code>    ——黄寿祺、张善文《周易译注》（上海古籍出版社，1989年）
</code></pre></blockquote><h3 id="_3-3-孔子与十翼" tabindex="-1">3.3 孔子与十翼 <a class="header-anchor" href="#_3-3-孔子与十翼" aria-label="Permalink to &quot;3.3 孔子与十翼&quot;">​</a></h3><p>【原典】《史记·孔子世家》，西汉·司马迁<br> 【原文】**孔子晚而喜《易》，序《彖》《系》《象》《说卦》《文言》。<br> **<strong>读《易》，韦编三绝。</strong></p><p><strong>十翼为《周易》的十篇解说文字：</strong></p><ul><li>彖传上·彖传下（解释卦辞）</li><li>象传上·象传下（解释卦象与爻辞）</li><li>系辞上·系辞下（哲学总论）</li><li>文言传（专解乾坤两卦）</li><li>说卦传（解说八卦属性）</li><li>序卦传（解说六十四卦排列顺序）</li><li>杂卦传（对卦关系总结）</li></ul><p><strong>考据说明：</strong></p><p>&quot;孔子作十翼&quot;的说法，同样存在争议。现代学者多认为：十翼并非孔子一人所作，而是孔门弟子及后学在战国至秦汉间陆续整理完成的文献集合。</p><blockquote><p>司马迁的记载，反映的是汉代的通行说法，不能直接等同于历史事实。</p><p>——谢金良《本世纪〈易经〉来源问题研究的若干考辨》（《福建论坛》，1998年）</p></blockquote><h3 id="_3-4-《周易》成书时间线-学界基本共识" tabindex="-1">3.4 《周易》成书时间线（学界基本共识） <a class="header-anchor" href="#_3-4-《周易》成书时间线-学界基本共识" aria-label="Permalink to &quot;3.4 《周易》成书时间线（学界基本共识）&quot;">​</a></h3><p>约商代晚期（公元前13—11世纪）</p><p>六爻数字卦符号已存在（甲骨文·考古证据）</p><p>约西周初期（公元前11世纪）</p><p>卦辞写定（周初史官群体，文王参与可能性存在）</p><p>爻辞写定（西周初至中期）</p><p>约战国至秦汉（公元前5—前2世纪）</p><p>十翼陆续写定（孔门后学）</p><p>西汉（公元前2世纪）</p><p>《周易》经传合编，成为今日通行本面貌</p><hr><h2 id="四、六十四卦的结构-一卦解剖" tabindex="-1">四、六十四卦的结构：一卦解剖 <a class="header-anchor" href="#四、六十四卦的结构-一卦解剖" aria-label="Permalink to &quot;四、六十四卦的结构：一卦解剖&quot;">​</a></h2><p>在进入六十四卦之前，必须先搞清楚一卦的内部结构。</p><h3 id="_4-1-一卦的解剖图" tabindex="-1">4.1 一卦的解剖图 <a class="header-anchor" href="#_4-1-一卦的解剖图" aria-label="Permalink to &quot;4.1 一卦的解剖图&quot;">​</a></h3><p>以<strong>乾卦</strong>（☰☰）为例：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>      ──────   上爻（第六爻）·上九</span></span>
<span class="line"><span>      ──  ──   五爻（第五爻）·六五</span></span>
<span class="line"><span>      ──────   四爻（第四爻）·九四</span></span>
<span class="line"><span>             ↖︎ 上卦（外卦）与下卦（内卦）的分界</span></span>
<span class="line"><span>      ──  ──   三爻（第三爻）·六三</span></span>
<span class="line"><span>      ──────   二爻（第二爻）·九二</span></span>
<span class="line"><span>      ──────   初爻（第一爻）·初九</span></span>
<span class="line"><span></span></span>
<span class="line"><span>读卦方向：从下往上读（初爻在下，上爻在上）</span></span></code></pre></div><h3 id="_4-2-爻的命名规则" tabindex="-1">4.2 爻的命名规则 <a class="header-anchor" href="#_4-2-爻的命名规则" aria-label="Permalink to &quot;4.2 爻的命名规则&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阳爻（——）= 九</span></span>
<span class="line"><span>阴爻（--）= 六</span></span>
<span class="line"><span></span></span>
<span class="line"><span>命名格式：位置 + 阴阳</span></span>
<span class="line"><span>  初九 = 第一爻·阳</span></span>
<span class="line"><span>  九二 = 第二爻·阳</span></span>
<span class="line"><span>  六三 = 第三爻·阴</span></span>
<span class="line"><span>  九四 = 第四爻·阳</span></span>
<span class="line"><span>  六五 = 第五爻·阴</span></span>
<span class="line"><span>  上九 = 第六爻·阳</span></span>
<span class="line"><span></span></span>
<span class="line"><span>为什么阳爻叫&quot;九&quot;，阴爻叫&quot;六&quot;？</span></span>
<span class="line"><span>  九 = 老阳之数（最大的阳数）</span></span>
<span class="line"><span>  六 = 老阴之数（最大的阴数）</span></span>
<span class="line"><span>  来源：大衍筮法的数字系统</span></span>
<span class="line"><span>  ——《周易·系辞上传》第九章</span></span></code></pre></div><h3 id="_4-3-卦的三个层次" tabindex="-1">4.3 卦的三个层次 <a class="header-anchor" href="#_4-3-卦的三个层次" aria-label="Permalink to &quot;4.3 卦的三个层次&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每一卦，包含三个层次的信息：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>① 卦象（符号）</span></span>
<span class="line"><span>  六爻的阴阳排列 = 视觉符号</span></span>
<span class="line"><span>  = 最直观的信息层</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 卦辞（文字）</span></span>
<span class="line"><span>  对整卦情境的总体描述</span></span>
<span class="line"><span>  = 文王（或周初史官）所写</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 爻辞（文字）</span></span>
<span class="line"><span>  对每一爻具体变化节点的描述</span></span>
<span class="line"><span>  = 周公（或西周史官）所写</span></span>
<span class="line"><span>  = 六十四卦 × 六爻 = 384条爻辞</span></span>
<span class="line"><span>    （加上乾坤两卦各有&quot;用九&quot;&quot;用六&quot;，共386条）</span></span></code></pre></div><hr><h2 id="五、六十四卦总览-序卦的逻辑" tabindex="-1">五、六十四卦总览：序卦的逻辑 <a class="header-anchor" href="#五、六十四卦总览-序卦的逻辑" aria-label="Permalink to &quot;五、六十四卦总览：序卦的逻辑&quot;">​</a></h2><p>六十四卦不是随机排列的。它们的顺序，有内在逻辑。</p><p>【原典】《周易·序卦传》<br> 【原文（节选）】<strong>有天地，然后万物生焉……有万物，然后有男女；有男女，然后有夫妇，有夫妇，然后有父子……</strong></p><p>《序卦传》解释了六十四卦的排列逻辑：<br><strong>从宇宙起源，到人伦社会，是一部完整的&quot;宇宙演化史&quot;。</strong></p><h3 id="_5-1-六十四卦排列结构" tabindex="-1">5.1 六十四卦排列结构 <a class="header-anchor" href="#_5-1-六十四卦排列结构" aria-label="Permalink to &quot;5.1 六十四卦排列结构&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上经（第1—30卦）：以乾坤为首，讲天地宇宙与自然规律</span></span>
<span class="line"><span>下经（第31—64卦）：以咸恒为首，讲人伦社会与人生百态</span></span>
<span class="line"><span></span></span>
<span class="line"><span>上经首卦：乾（☰☰）= 天·纯阳·创始</span></span>
<span class="line"><span>上经末卦：离（☲☲）= 火·日·文明</span></span>
<span class="line"><span></span></span>
<span class="line"><span>下经首卦：咸（☱☶）= 泽山·感应·男女相感</span></span>
<span class="line"><span>下经末卦：未济（☲☵）= 火水未济·未完成·永恒的开放</span></span></code></pre></div><p>六十四卦以<strong>未济</strong>（未完成）结尾，不是以&quot;既济&quot;（完成）结尾——这是《周易》最深刻的哲学态度之一。</p><p><strong>宇宙永远处于未完成状态，变化永无终止。</strong></p><h3 id="_5-2-六十四卦完整列表" tabindex="-1">5.2 六十四卦完整列表 <a class="header-anchor" href="#_5-2-六十四卦完整列表" aria-label="Permalink to &quot;5.2 六十四卦完整列表&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上经（1—30卦）：</span></span>
<span class="line"><span>01乾  02坤  03屯  04蒙  05需  06讼</span></span>
<span class="line"><span>07师  08比  09小畜 10履  11泰  12否</span></span>
<span class="line"><span>13同人 14大有 15谦  16豫  17随  18蛊</span></span>
<span class="line"><span>19临  20观  21噬嗑 22贲  23剥  24复</span></span>
<span class="line"><span>25无妄 26大畜 27颐  28大过 29坎  30离</span></span>
<span class="line"><span></span></span>
<span class="line"><span>下经（31—64卦）：</span></span>
<span class="line"><span>31咸  32恒  33遁  34大壮 35晋  36明夷</span></span>
<span class="line"><span>37家人 38睽  39蹇  40解  41损  42益</span></span>
<span class="line"><span>43夬  44姤  45萃  46升  47困  48井</span></span>
<span class="line"><span>49革  50鼎  51震  52艮  53渐  54归妹</span></span>
<span class="line"><span>55丰  56旅  57巽  58兑  59涣  60节</span></span>
<span class="line"><span>61中孚 62小过 63既济 64未济</span></span></code></pre></div><h2 id="六、六十四卦的核心关系-八种卦变全解" tabindex="-1">六、六十四卦的核心关系：八种卦变全解 <a class="header-anchor" href="#六、六十四卦的核心关系-八种卦变全解" aria-label="Permalink to &quot;六、六十四卦的核心关系：八种卦变全解&quot;">​</a></h2><p>六十四卦不是孤立存在的。<br> 每一卦，都可以通过多种方式，衍生出与之相关的卦——<br> 这些关系，构成了《周易》及后世六爻占卜的完整工具箱。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一卦在手，多卦可得：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  本卦 → 互卦（取中间四爻重组）</span></span>
<span class="line"><span>       → 变卦（某爻阴阳互换）</span></span>
<span class="line"><span>       → 错卦（全部爻阴阳互换）</span></span>
<span class="line"><span>       → 综卦（整卦上下翻转）</span></span>
<span class="line"><span>       → 伏卦（宫主卦为参照）</span></span>
<span class="line"><span>       → 游魂卦 / 归魂卦（八宫流变中的特殊位置）</span></span>
<span class="line"><span>       → 世爻 / 应爻（六爻体系的主客定位）</span></span></code></pre></div><h3 id="_6-1-本卦" tabindex="-1">6.1 本卦 <a class="header-anchor" href="#_6-1-本卦" aria-label="Permalink to &quot;6.1 本卦&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>定义：</span></span>
<span class="line"><span>  占得的原始卦，即当下情境的直接呈现。</span></span>
<span class="line"><span>  是所有关系的起点与基础。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>功能：</span></span>
<span class="line"><span>  描述&quot;此刻是什么情境&quot;。</span></span>
<span class="line"><span>  是判断的第一层信息。</span></span></code></pre></div><p>本篇以**屯卦（水雷屯 ☵☳）**贯穿全节示例。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>屯卦结构：</span></span>
<span class="line"><span>  上卦：坎（☵）= 阴·阳·阴（从下到上）</span></span>
<span class="line"><span>  下卦：震（☳）= 阳·阴·阴（从下到上）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>六爻（从下到上）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  上爻 ── ──  上六（阴）</span></span>
<span class="line"><span>  五爻 ─────  九五（阳）</span></span>
<span class="line"><span>  四爻 ── ──  六四（阴）</span></span>
<span class="line"><span>             上卦／下卦分界</span></span>
<span class="line"><span>  三爻 ── ──  六三（阴）</span></span>
<span class="line"><span>  二爻 ── ──  六二（阴）</span></span>
<span class="line"><span>  初爻 ─────  初九（阳）</span></span></code></pre></div><blockquote><p><strong>屯：元亨，利贞，勿用有攸往，利建侯。 ——《周易·屯卦·卦辞》</strong></p></blockquote><p>虽然亨通，但不宜轻举妄动，适合建立根基、寻求支持。</p><h3 id="_6-2-互卦-互体卦" tabindex="-1">6.2 互卦（互体卦） <a class="header-anchor" href="#_6-2-互卦-互体卦" aria-label="Permalink to &quot;6.2 互卦（互体卦）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>定义：</span></span>
<span class="line"><span>  取本卦第二、三、四爻组成下互卦，</span></span>
<span class="line"><span>  取本卦第三、四、五爻组成上互卦，</span></span>
<span class="line"><span>  两者合成一个新的六爻卦。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>取法：</span></span>
<span class="line"><span>  下互卦234    </span></span>
<span class="line"><span>  上互卦345</span></span>
<span class="line"><span></span></span>
<span class="line"><span>功能：</span></span>
<span class="line"><span>  揭示情境内部隐藏的结构与潜在动力。</span></span>
<span class="line"><span>  事物表面之下，暗中运作的力量。</span></span></code></pre></div><p><strong>屯卦互卦示例：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>屯卦六爻（从下到上）：阳·阴·阴·阴·阳·阴</span></span>
<span class="line"><span></span></span>
<span class="line"><span>下互卦 = 取二三四爻：阴·阴·阴 = 坤（☷）</span></span>
<span class="line"><span>上互卦 = 取三四五爻：阴·阴·阳 = 艮（☶）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>互卦 = 山地剥（☶☷）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>解读：</span></span>
<span class="line"><span>  屯卦表面是&quot;艰难起步&quot;，</span></span>
<span class="line"><span>  互卦剥卦（剥落、削减）暗示：</span></span>
<span class="line"><span>  内部正在经历消耗与剥蚀，</span></span>
<span class="line"><span>  需特别警惕内部损耗与人心涣散。</span></span></code></pre></div><blockquote><p>【原典依据】《左传·成公十六年》筮例中已有互体用法的实际记录，是互卦见于文献的最早证据之一。 ——高亨《周易古经今注》（中华书局，1984年）</p></blockquote><h3 id="_6-3-变卦-之卦" tabindex="-1">6.3 变卦（之卦） <a class="header-anchor" href="#_6-3-变卦-之卦" aria-label="Permalink to &quot;6.3 变卦（之卦）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>定义：</span></span>
<span class="line"><span>  将本卦中某一爻（或数爻）阴阳互换，</span></span>
<span class="line"><span>  得到新的卦，称为变卦，又称&quot;之卦&quot;。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  &quot;本卦之变卦&quot;写法示例：</span></span>
<span class="line"><span>  &quot;屯之比&quot; = 屯卦初爻变动，变成比卦。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>取法：</span></span>
<span class="line"><span>  占筮时，通过蓍草或铜钱演算，</span></span>
<span class="line"><span>  出现&quot;老阳&quot;（9）或&quot;老阴&quot;（6）的爻，即为变爻。</span></span>
<span class="line"><span>  老阳变阴，老阴变阳。（少阳·少阴不变）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>功能：</span></span>
<span class="line"><span>  描述&quot;情境将如何发展&quot;。</span></span>
<span class="line"><span>  本卦 = 现在，变卦 = 未来趋势。</span></span>
<span class="line"><span>  = 动态推演的核心工具。</span></span></code></pre></div><p><strong>屯卦变卦示例（以初爻变为例）：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>屯卦初爻（初九·阳爻）为变爻：</span></span>
<span class="line"><span>  初爻：阳（─────）→ 变为 阴（── ──）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>变后六爻（从下到上）：阴·阴·阴·阴·阳·阴</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  下卦（初二三爻）= 阴·阴·阴 = 坤（☷）</span></span>
<span class="line"><span>  上卦（四五六爻）= 阴·阳·阴 = 坎（☵）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>变卦 = 水地比（☵☷）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>解读：</span></span>
<span class="line"><span>  屯（艰难起步）→ 比（亲比团结）：</span></span>
<span class="line"><span>  艰难之中，寻求联合与支持，化解孤立、建立支持网络，是当前情境的发展方向。</span></span></code></pre></div><p><strong>变爻的读法规则：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>无变爻：  读卦辞，看整体情境。</span></span>
<span class="line"><span>一个变爻：读该变爻的爻辞，最为准确。</span></span>
<span class="line"><span>两个变爻：读上位变爻的爻辞为主。</span></span>
<span class="line"><span>三个变爻：读本卦卦辞与变卦卦辞，各取一半。</span></span>
<span class="line"><span>四个变爻：读变卦中不变的两爻，以下爻为主。</span></span>
<span class="line"><span>五个变爻：读变卦卦辞。</span></span>
<span class="line"><span>六个变爻：乾坤两卦读&quot;用九&quot;&quot;用六&quot;；</span></span>
<span class="line"><span>           其余卦读变卦卦辞。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>——《卜筮正宗》（清·王洪绪）</span></span></code></pre></div><h3 id="_6-4-错卦-旁通卦" tabindex="-1">6.4 错卦（旁通卦） <a class="header-anchor" href="#_6-4-错卦-旁通卦" aria-label="Permalink to &quot;6.4 错卦（旁通卦）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>定义：</span></span>
<span class="line"><span>  将本卦所有爻阴阳互换（全部取反），</span></span>
<span class="line"><span>  得到错卦，又称&quot;旁通卦&quot;。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>取法：</span></span>
<span class="line"><span>  本卦每一爻：阳→阴，阴→阳，全部互换。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>功能：</span></span>
<span class="line"><span>  揭示情境的&quot;对立面&quot;与&quot;互补面&quot;。</span></span>
<span class="line"><span>  = 当前情境的镜像，完全相反的状态。</span></span>
<span class="line"><span>  提示：此刻缺少的是什么？对立面在说什么？</span></span></code></pre></div><p><strong>屯卦错卦示例：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>屯卦六爻(从下到上)：阳·阴·阴·阴·阳·阴</span></span>
<span class="line"><span>全部互换后：       阴·阳·阳·阳·阴·阳</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  下卦（初二三爻）= 阴·阳·阳 = 巽（☴）</span></span>
<span class="line"><span>  上卦（四五六爻）= 阳·阴·阳 = 离（☲）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>错卦 = 火风鼎（☲☴）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>解读：</span></span>
<span class="line"><span>  屯（艰难起步·水雷）的错卦是鼎（稳定成就·火风）。</span></span>
<span class="line"><span>  错卦提示对立面：此刻艰难，</span></span>
<span class="line"><span>  目标方向是走向鼎的稳定与成熟状态。</span></span></code></pre></div><p><strong>六十四卦错卦对照（部分）：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾（☰☰）↔ 坤（☷☷）</span></span>
<span class="line"><span>坎（☵☵）↔ 离（☲☲）</span></span>
<span class="line"><span>屯（☵☳）↔ 鼎（☲☴）</span></span>
<span class="line"><span>蒙（☶☵）↔ 革（☱☲）</span></span>
<span class="line"><span>需（☵☰）↔ 晋（☲☷）</span></span>
<span class="line"><span>讼（☰☵）↔ 明夷（☷☲）</span></span></code></pre></div><blockquote><p>【原典依据】&quot;旁通&quot;一词由东汉虞翻在《周易注》中系统提出，是错卦理论的最早系统表述。</p></blockquote><h3 id="_6-5-综卦-覆卦" tabindex="-1">6.5 综卦（覆卦） <a class="header-anchor" href="#_6-5-综卦-覆卦" aria-label="Permalink to &quot;6.5 综卦（覆卦）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>定义：</span></span>
<span class="line"><span>  将本卦整体上下翻转180°，</span></span>
<span class="line"><span>  得到综卦，又称&quot;覆卦&quot;。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>取法：</span></span>
<span class="line"><span>  本卦上爻 → 新卦初爻</span></span>
<span class="line"><span>  本卦五爻 → 新卦二爻</span></span>
<span class="line"><span>  本卦四爻 → 新卦三爻</span></span>
<span class="line"><span>  本卦三爻 → 新卦四爻</span></span>
<span class="line"><span>  本卦二爻 → 新卦五爻</span></span>
<span class="line"><span>  本卦初爻 → 新卦上爻</span></span>
<span class="line"><span>  = 整卦倒过来读。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>功能：</span></span>
<span class="line"><span>  揭示&quot;换个角度看同一情境&quot;。</span></span>
<span class="line"><span>  = 你看到的是屯，对方看到的是蒙。</span></span>
<span class="line"><span>  = 同一件事，立场不同，卦象不同。</span></span>
<span class="line"><span>  提示：不要只站在自己的角度判断。</span></span></code></pre></div><p><strong>屯卦综卦示例：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>屯卦六爻(从下到上) 阳·阴·阴·阴·阳·阴</span></span>
<span class="line"><span>上下翻转(从下到上) 阴·阳·阴·阴·阴·阳</span></span>
<span class="line"><span></span></span>
<span class="line"><span>上卦（四五六爻）= 阴·阴·阳 = 艮（☶）</span></span>
<span class="line"><span>下卦（初二三爻）= 阴·阳·阴 = 坎（☵）</span></span>
<span class="line"><span>综卦 = 山水蒙（☶☵）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>解读：</span></span>
<span class="line"><span>  你正在艰难起步（屯），</span></span>
<span class="line"><span>  对方眼中你是蒙昧未开（蒙）——</span></span>
<span class="line"><span>  同一个情境，两种视角，互为镜像。</span></span>
<span class="line"><span>  提示：此刻需要启蒙与引导，不要急于求成。</span></span></code></pre></div><p><strong>特殊情况：综卦等于本卦（非覆卦）</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有8个卦，翻转后等于自身，称为&quot;非覆卦&quot;：</span></span>
<span class="line"><span>  乾（☰☰）  坤（☷☷）</span></span>
<span class="line"><span>  坎（☵☵）  离（☲☲）</span></span>
<span class="line"><span>  颐（☶☳）  大过（☱☴）</span></span>
<span class="line"><span>  中孚（☴☱）小过（☳☶）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这8个卦，上下翻转后卦象不变，</span></span>
<span class="line"><span>说明它们描述的情境具有&quot;方向无关性&quot;——</span></span>
<span class="line"><span>无论从哪个角度看，都是同一个状态。</span></span></code></pre></div><blockquote><p>【原典依据】《周易·杂卦传》：对六十四卦两两对比关系的系统总结。<br> ——向世陵《&quot;重&quot;&quot;错&quot;之义与六十四卦的生成》（《周易研究》，2001年）</p></blockquote><h3 id="_6-6-伏卦-飞伏卦" tabindex="-1">6.6 伏卦（飞伏卦） <a class="header-anchor" href="#_6-6-伏卦-飞伏卦" aria-label="Permalink to &quot;6.6 伏卦（飞伏卦）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>定义：</span></span>
<span class="line"><span>  每一卦，都有一个对应的&quot;伏卦&quot;。</span></span>
<span class="line"><span>  伏卦 = 该卦所属八宫的宫主卦（八纯卦）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  飞爻 = 本卦各爻（显现于外的）</span></span>
<span class="line"><span>  伏爻 = 宫主卦对应位置的爻（隐藏于内的）</span></span>
<span class="line"><span>  飞与伏，一显一隐，互为表里。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>功能：</span></span>
<span class="line"><span>  揭示卦中隐藏的、未显现的信息。</span></span>
<span class="line"><span>  在六爻占卜中，若某五行在本卦飞爻中找不到，</span></span>
<span class="line"><span>  则去伏爻中寻找，称为&quot;取用神于伏爻&quot;。</span></span>
<span class="line"><span>  = 伏卦是六爻占卜中寻找&quot;隐藏用神&quot;的工具。</span></span></code></pre></div><p><strong>屯卦伏卦示例：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>屯卦属于坎宫，宫主卦为&quot;坎为水（☵☵）&quot;。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>坎卦六爻（从下到上）：阴·阳·阴·阴·阳·阴</span></span>
<span class="line"><span>屯卦六爻（从下到上）：阳·阴·阴·阴·阳·阴</span></span>
<span class="line"><span></span></span>
<span class="line"><span>飞爻（屯卦）vs 伏爻（坎为水）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  初爻：飞=阳（初九）  伏=阴（初六）  → 不同，伏爻藏阴</span></span>
<span class="line"><span>  二爻：飞=阴（六二）  伏=阳（九二）  → 不同，伏爻藏阳</span></span>
<span class="line"><span>  三爻：飞=阴（六三）  伏=阴（六三）  → 相同，伏爻不显</span></span>
<span class="line"><span>  四爻：飞=阴（六四）  伏=阴（六四）  → 相同，伏爻不显</span></span>
<span class="line"><span>  五爻：飞=阳（九五）  伏=阳（九五）  → 相同，伏爻不显</span></span>
<span class="line"><span>  上爻：飞=阴（上六）  伏=阴（上六）  → 相同，伏爻不显</span></span>
<span class="line"><span></span></span>
<span class="line"><span>解读：</span></span>
<span class="line"><span>  屯卦初爻、二爻的飞伏不同，</span></span>
<span class="line"><span>  说明这两个位置有隐藏信息——</span></span>
<span class="line"><span>  初爻之下藏着阴的力量，</span></span>
<span class="line"><span>  二爻之下藏着阳的力量，</span></span>
<span class="line"><span>  是占断时需要特别留意的隐伏之处。</span></span></code></pre></div><blockquote><p>【原典依据】<br> ——《增删卜易》（清·野鹤老人）<br> ——《卜筮正宗》（清·王洪绪）</p></blockquote><p>伏卦理论源于京房《京氏易传》（西汉），是汉代象数易学的重要组成部分。</p><h3 id="_6-7-八宫与八纯卦" tabindex="-1">6.7 八宫与八纯卦 <a class="header-anchor" href="#_6-7-八宫与八纯卦" aria-label="Permalink to &quot;6.7 八宫与八纯卦&quot;">​</a></h3><h4 id="来源" tabindex="-1">来源： <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源：&quot;">​</a></h4><p>西汉·京房（前77—前37年）在《京氏易传》中创立&quot;八宫卦&quot;体系，将六十四卦按八纯卦归宫，每宫8卦，共64卦，是后世六爻占卜的基础框架。</p><p>八纯卦（宫主卦），即八卦自身相叠的卦，上下卦相同。例：</p><ul><li>乾为天（☰☰）坎为水（☵☵）艮为山（☶☶）震为雷（☳☳）</li><li>巽为风（☴☴）离为火（☲☲）坤为地（☷☷）兑为泽（☱☱）</li></ul><h4 id="八纯卦的特点" tabindex="-1">八纯卦的特点： <a class="header-anchor" href="#八纯卦的特点" aria-label="Permalink to &quot;八纯卦的特点：&quot;">​</a></h4><p>① 是本宫的&quot;宗主&quot;，代表该宫的纯粹能量</p><p>② 是本宫所有卦的&quot;伏卦&quot;参照基准</p><p>③ 在六爻占卜中，八纯卦的上爻为世爻</p><h4 id="八宫卦完整归属表" tabindex="-1">八宫卦完整归属表： <a class="header-anchor" href="#八宫卦完整归属表" aria-label="Permalink to &quot;八宫卦完整归属表：&quot;">​</a></h4><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>宫名      五行  八纯卦    一世      二世      三世      四世      五世      游魂      归魂</span></span>
<span class="line"><span>──────────────────────────────────────────────────────────────────────────────────</span></span>
<span class="line"><span>乾宫（金） 乾为天  天风姤    天山遁    天地否    风地观    山地剥    火地晋    火天大有</span></span>
<span class="line"><span>坎宫（水） 坎为水  水泽节    水雷屯    水火既济  泽火革    雷火丰    地火明夷  地水师</span></span>
<span class="line"><span>艮宫（土） 艮为山  山火贲    山天大畜  山泽损    火泽睽    天泽履    风泽中孚  风山渐</span></span>
<span class="line"><span>震宫（木） 震为雷  雷地豫    雷水解    雷风恒    地风升    水风井    泽风大过  泽雷随</span></span>
<span class="line"><span>巽宫（木） 巽为风  风天小畜  风火家人  风雷益    天雷无妄  火雷噬嗑  山雷颐    山风蛊</span></span>
<span class="line"><span>离宫（火） 离为火  火山旅    火风鼎    火水未济  山水蒙    风水涣    天水讼    天火同人</span></span>
<span class="line"><span>坤宫（土） 坤为地  地雷复    地泽临    地天泰    雷天大壮  泽天夬    水天需    水地比</span></span>
<span class="line"><span>兑宫（金） 兑为泽  泽水困    泽地萃    泽山咸    水山蹇    地山谦    雷山小过  雷泽归妹</span></span></code></pre></div><blockquote><p>【原典依据】京房《京氏易传》（西汉）是八宫卦体系的源头文献。</p></blockquote><h3 id="_6-8-世爻与应爻-六爻体系基础" tabindex="-1">6.8 世爻与应爻（六爻体系基础） <a class="header-anchor" href="#_6-8-世爻与应爻-六爻体系基础" aria-label="Permalink to &quot;6.8 世爻与应爻（六爻体系基础）&quot;">​</a></h3><blockquote><p>说明：世爻与应爻是六爻占卜（纳甲筮法）的核心概念，本节仅作基础科普，不展开六爻占断的完整体系。</p></blockquote><p><strong>世爻：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>定义：</span></span>
<span class="line"><span>  每一卦中，代表&quot;占卜者自身&quot;或&quot;所问之事主体&quot;的爻，</span></span>
<span class="line"><span>  称为世爻。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  世爻的位置，由该卦在八宫中的&quot;世数&quot;决定：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  八纯卦（宫主）：上爻（第六爻）为世爻</span></span>
<span class="line"><span>  一世卦：        初爻为世爻</span></span>
<span class="line"><span>  二世卦：        二爻为世爻</span></span>
<span class="line"><span>  三世卦：        三爻为世爻</span></span>
<span class="line"><span>  四世卦：        四爻为世爻</span></span>
<span class="line"><span>  五世卦：        五爻为世爻</span></span>
<span class="line"><span>  游魂卦：        四爻为世爻（退回四爻）</span></span>
<span class="line"><span>  归魂卦：        三爻为世爻（内卦归宗）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>功能：</span></span>
<span class="line"><span>  世爻 = 主体、自己、所问之事的核心。</span></span>
<span class="line"><span>  世爻的旺衰，直接反映主体的强弱与事情的走向。</span></span></code></pre></div><p><strong>应爻：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>定义：</span></span>
<span class="line"><span>  与世爻相对应的爻，称为应爻。</span></span>
<span class="line"><span>  = 对方、他人、事情的客体、外部环境。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>对应规律（世应相距三爻）：</span></span>
<span class="line"><span>  世爻在初爻 → 应爻在四爻</span></span>
<span class="line"><span>  世爻在二爻 → 应爻在五爻</span></span>
<span class="line"><span>  世爻在三爻 → 应爻在六爻（上爻）</span></span>
<span class="line"><span>  世爻在四爻 → 应爻在初爻</span></span>
<span class="line"><span>  世爻在五爻 → 应爻在二爻</span></span>
<span class="line"><span>  世爻在六爻 → 应爻在三爻</span></span>
<span class="line"><span></span></span>
<span class="line"><span>功能：</span></span>
<span class="line"><span>  应爻 = 客体、对方、外部条件。</span></span>
<span class="line"><span>  世应关系，反映主客双方的互动状态。</span></span></code></pre></div><p><strong>世应关系的基本判断：</strong></p><ul><li>世应相生：主客互利，事情顺遂。</li><li>世应相克：主客对立，存在阻力。</li><li>世克应：我能控制对方，主动有力。</li><li>应克世：对方压制我方，被动受制。</li><li>世应比和：阴阳相同，关系平淡，无明显助力或阻力。</li><li>世应相冲：主客矛盾激烈，事情多变。</li></ul><p><strong>屯卦世应示例：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>屯卦属坎宫二世卦，世爻在二爻。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  上爻 ── ──  上六</span></span>
<span class="line"><span>  五爻 ─────  九五  ← 应爻（与二爻相距三位）</span></span>
<span class="line"><span>  四爻 ── ──  六四</span></span>
<span class="line"><span>  三爻 ── ──  六三</span></span>
<span class="line"><span>  二爻 ── ──  六二  ← 世爻（二世卦，世在二爻）</span></span>
<span class="line"><span>  初爻 ─────  初九</span></span>
<span class="line"><span></span></span>
<span class="line"><span>世爻 = 六二（阴）</span></span>
<span class="line"><span>应爻 = 九五（阳）</span></span>
<span class="line"><span>世应关系：阴阳相应，有呼应之象，</span></span>
<span class="line"><span>          但世爻为阴、力弱，应爻为阳、力强，</span></span>
<span class="line"><span>          = 主体力量不足，需借助外力（应爻）支持。</span></span>
<span class="line"><span>          与屯卦&quot;利建侯&quot;（寻求支持）的卦辞完全吻合。</span></span></code></pre></div><blockquote><p>【原典依据】京房《京氏易传》（西汉）：世应爻理论的源头。<br> 《火珠林》（五代·麻衣道者，托名）：世应判断规则的系统整理，是六爻占卜的奠基文献。</p></blockquote><h3 id="_6-9-游魂卦与归魂卦" tabindex="-1">6.9 游魂卦与归魂卦 <a class="header-anchor" href="#_6-9-游魂卦与归魂卦" aria-label="Permalink to &quot;6.9 游魂卦与归魂卦&quot;">​</a></h3><h4 id="游魂卦背景" tabindex="-1">游魂卦背景 <a class="header-anchor" href="#游魂卦背景" aria-label="Permalink to &quot;游魂卦背景&quot;">​</a></h4><p>在八宫卦体系中，每宫八卦按&quot;世爻&quot;位置，从初爻依次上升至五爻（一世→五世），之后不再继续上升，而是发生两次特殊变化，从而产生游魂卦与归魂卦。</p><h4 id="游魂卦定义" tabindex="-1">游魂卦定义 <a class="header-anchor" href="#游魂卦定义" aria-label="Permalink to &quot;游魂卦定义&quot;">​</a></h4><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>定义：</span></span>
<span class="line"><span>  五世卦的上卦（外卦）三爻全部变回本宫八纯卦的上卦，</span></span>
<span class="line"><span>  世爻退回第四爻，称为游魂卦。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  &quot;游魂&quot;= 魂魄离体游荡，有去无归之象。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>特点：</span></span>
<span class="line"><span>  ① 世爻在四爻</span></span>
<span class="line"><span>  ② 外卦（上卦）已变回本宫纯卦的上卦</span></span>
<span class="line"><span>  ③ 内卦（下卦）与五世卦相同，尚未归宗</span></span>
<span class="line"><span></span></span>
<span class="line"><span>象意：</span></span>
<span class="line"><span>  游离、漂泊、变动不居、根基不稳。</span></span>
<span class="line"><span>  事情处于游移状态，尚未有定论。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>示例：</span></span>
<span class="line"><span>  乾宫游魂卦 = 火地晋（☲☷）</span></span>
<span class="line"><span>  乾宫五世卦&quot;山地剥&quot;的上卦变回乾宫上卦乾→离，世爻退至四爻</span></span></code></pre></div><p><strong>归魂卦：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>定义：</span></span>
<span class="line"><span>  游魂卦的内卦（下卦）三爻全部变回本宫八纯卦的下卦，</span></span>
<span class="line"><span>  世爻在第三爻，称为归魂卦。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  &quot;归魂&quot;= 游魂归位，落叶归根之象。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>特点：</span></span>
<span class="line"><span>  ① 世爻在三爻</span></span>
<span class="line"><span>  ② 内卦（下卦）恢复为本宫八纯卦的下卦</span></span>
<span class="line"><span>  ③ 外卦（上卦）与游魂卦相同</span></span>
<span class="line"><span></span></span>
<span class="line"><span>象意：</span></span>
<span class="line"><span>  回归、收束、落定、事情有了结果。</span></span>
<span class="line"><span>  适合收尾、回归本源，不宜再大幅变动。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>示例：</span></span>
<span class="line"><span>  乾宫归魂卦 = 火天大有（☲☰）</span></span>
<span class="line"><span>  （游魂卦&quot;火地晋&quot;的下卦变回乾宫下卦坤→乾，世爻在三爻）</span></span></code></pre></div><p><strong>游魂归魂的哲学含义：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一世→五世：阳气（或阴气）逐步上升，事物由弱到强。</span></span>
<span class="line"><span>游魂：      到达极点后，开始游离，无所归依。</span></span>
<span class="line"><span>归魂：      游离之后，最终回归本源，落叶归根。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 任何事物的发展，都遵循&quot;生长→极盛→游离→归根&quot;的轨迹。</span></span>
<span class="line"><span>= 归魂卦，是一个周期的终点，也是下一个周期的起点。</span></span></code></pre></div><p>【原典依据】<br> 京房《京氏易传》（西汉）<br> 郭璞《葬书》中亦有游魂归魂的引申应用（东晋）</p><h3 id="_6-10-八种关系综合对比" tabindex="-1">6.10 八种关系综合对比 <a class="header-anchor" href="#_6-10-八种关系综合对比" aria-label="Permalink to &quot;6.10 八种关系综合对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">名称</th><th style="text-align:left;">操作方式</th><th style="text-align:left;">揭示内容</th><th style="text-align:center;">所属体系</th></tr></thead><tbody><tr><td style="text-align:center;">本卦</td><td style="text-align:left;">原始卦象</td><td style="text-align:left;">当下情境是什么</td><td style="text-align:center;">通用</td></tr><tr><td style="text-align:center;">互卦</td><td style="text-align:left;">取二三四爻与三四五爻重组</td><td style="text-align:left;">内部隐藏的结构</td><td style="text-align:center;">通用</td></tr><tr><td style="text-align:center;">变卦</td><td style="text-align:left;">变爻阴阳互换</td><td style="text-align:left;">情境的发展趋势</td><td style="text-align:center;">通用</td></tr><tr><td style="text-align:center;">错卦</td><td style="text-align:left;">全部爻阴阳互换</td><td style="text-align:left;">对立面与互补面</td><td style="text-align:center;">通用</td></tr><tr><td style="text-align:center;">综卦</td><td style="text-align:left;">整卦上下翻转</td><td style="text-align:left;">换角度看同一情境</td><td style="text-align:center;">通用</td></tr><tr><td style="text-align:center;">伏卦</td><td style="text-align:left;">以宫主卦为参照</td><td style="text-align:left;">隐藏未显的信息</td><td style="text-align:center;">六爻占卜</td></tr><tr><td style="text-align:center;">游魂／归魂</td><td style="text-align:left;">八宫流变的特殊位置</td><td style="text-align:left;">事物游离与归根的状态</td><td style="text-align:center;">六爻占卜</td></tr><tr><td style="text-align:center;">世爻／应爻</td><td style="text-align:left;">八宫世数定位</td><td style="text-align:left;">主客关系与强弱对比</td><td style="text-align:center;">六爻占卜</td></tr></tbody></table><p><strong>一句话记忆法：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本卦 = 我是谁（当下）</span></span>
<span class="line"><span>互卦 = 我内部在发生什么（隐藏）</span></span>
<span class="line"><span>变卦 = 我将去哪里（趋势）</span></span>
<span class="line"><span>错卦 = 我的对立面是什么（镜像）</span></span>
<span class="line"><span>综卦 = 别人眼中的我是什么（视角）</span></span>
<span class="line"><span>伏卦 = 我身上还藏着什么（隐伏）</span></span>
<span class="line"><span>游魂 = 我是否已经游离失根（漂泊）</span></span>
<span class="line"><span>归魂 = 我是否正在回归本源（落定）</span></span>
<span class="line"><span>世应 = 我与对方的关系如何（主客）</span></span></code></pre></div><h3 id="_6-11-实战示例-屯卦多卦联读" tabindex="-1">6.11 实战示例：屯卦多卦联读 <a class="header-anchor" href="#_6-11-实战示例-屯卦多卦联读" aria-label="Permalink to &quot;6.11 实战示例：屯卦多卦联读&quot;">​</a></h3><p>以**屯卦（☵☳）**为例，综合运用：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本卦：水雷屯（☵☳）</span></span>
<span class="line"><span>  = 艰难起步，万物初生，困难重重，但生机勃勃。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>互卦：山地剥（☶☷）</span></span>
<span class="line"><span>  = 内部正在经历剥落与消耗，</span></span>
<span class="line"><span>    警惕内部损耗与人心涣散。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>变卦（初爻变）：水地比（☵☷）</span></span>
<span class="line"><span>  = 发展方向是寻求联合、亲比团结，</span></span>
<span class="line"><span>    化解孤立，建立支持网络。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>错卦：火风鼎（☲☴）</span></span>
<span class="line"><span>  = 对立面是稳定成熟的鼎盛状态，</span></span>
<span class="line"><span>    目标：走向稳定，建立制度。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>综卦：山水蒙（☶☵）</span></span>
<span class="line"><span>  = 换个角度：在外人眼中，</span></span>
<span class="line"><span>    此刻的艰难起步是蒙昧未开——</span></span>
<span class="line"><span>    需要启蒙与引导，不急于表现。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>伏卦：坎为水（☵☵）</span></span>
<span class="line"><span>  = 初爻、二爻有隐伏信息，</span></span>
<span class="line"><span>    初爻之下藏阴，二爻之下藏阳，</span></span>
<span class="line"><span>    需留意隐而未发的变数。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>八宫归属：坎宫二世卦</span></span>
<span class="line"><span>  世爻 = 六二（阴）  应爻 = 九五（阳）</span></span>
<span class="line"><span>  = 主体力弱，需借外力，</span></span>
<span class="line"><span>    与&quot;利建侯&quot;的卦辞完全吻合。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>综合解读：</span></span>
<span class="line"><span>  此刻艰难（本），内有暗耗（互），</span></span>
<span class="line"><span>  方向是联合（变），目标是稳定（错），</span></span>
<span class="line"><span>  外人看你尚未成熟（综），</span></span>
<span class="line"><span>  身上还有隐藏变数（伏），</span></span>
<span class="line"><span>  主体力量不足，需积极寻求支持（世应）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  = 踏实积累，广结善缘，</span></span>
<span class="line"><span>    不急于表现，内外兼顾，</span></span>
<span class="line"><span>    静待时机，方能化屯为比。</span></span></code></pre></div><h4 id="引用索引" tabindex="-1">引用索引 <a class="header-anchor" href="#引用索引" aria-label="Permalink to &quot;引用索引&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">引用内容</th><th style="text-align:left;">原典／来源</th><th style="text-align:left;">时代／年份</th></tr></thead><tbody><tr><td style="text-align:left;">互卦最早文献用例</td><td style="text-align:left;">《左传·成公十六年》筮例</td><td style="text-align:left;">春秋</td></tr><tr><td style="text-align:left;">互卦考证</td><td style="text-align:left;">高亨《周易古经今注》</td><td style="text-align:left;">中华书局，1984年</td></tr><tr><td style="text-align:left;">变爻读法规则</td><td style="text-align:left;">《卜筮正宗》（清·王洪绪）</td><td style="text-align:left;">清代</td></tr><tr><td style="text-align:left;">错综关系与六十四卦结构</td><td style="text-align:left;">向世陵《&quot;重&quot;&quot;错&quot;之义与六十四卦的生成》</td><td style="text-align:left;">《周易研究》，2001年</td></tr><tr><td style="text-align:left;">旁通（错卦）理论</td><td style="text-align:left;">虞翻《周易注》</td><td style="text-align:left;">东汉</td></tr><tr><td style="text-align:left;">八宫卦·伏卦·世应爻</td><td style="text-align:left;">京房《京氏易传》</td><td style="text-align:left;">西汉</td></tr><tr><td style="text-align:left;">伏卦取用神规则</td><td style="text-align:left;">《增删卜易》（清·野鹤老人）</td><td style="text-align:left;">清代</td></tr><tr><td style="text-align:left;">六爻世应判断</td><td style="text-align:left;">《火珠林》（五代·麻衣道者托名）</td><td style="text-align:left;">五代</td></tr><tr><td style="text-align:left;">游魂归魂引申应用</td><td style="text-align:left;">郭璞《葬书》</td><td style="text-align:left;">东晋</td></tr></tbody></table><h2 id="七、卦辞与爻辞-如何读一卦" tabindex="-1">七、卦辞与爻辞：如何读一卦 <a class="header-anchor" href="#七、卦辞与爻辞-如何读一卦" aria-label="Permalink to &quot;七、卦辞与爻辞：如何读一卦&quot;">​</a></h2><h3 id="_7-1-读卦的基本框架" tabindex="-1">7.1 读卦的基本框架 <a class="header-anchor" href="#_7-1-读卦的基本框架" aria-label="Permalink to &quot;7.1 读卦的基本框架&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一步：看卦名</span></span>
<span class="line"><span>  卦名往往直接点明情境。</span></span>
<span class="line"><span>  如&quot;屯&quot;= 艰难，&quot;蒙&quot;= 蒙昧，&quot;需&quot;= 等待。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第二步：读卦辞</span></span>
<span class="line"><span>  卦辞描述这个情境的总体性质与建议。</span></span>
<span class="line"><span>  格式通常是：情境描述 + 吉凶判断 + 行动建议</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第三步：定爻位</span></span>
<span class="line"><span>  根据具体问题，定位到相关爻。</span></span>
<span class="line"><span>  初爻 = 事情开始阶段</span></span>
<span class="line"><span>  二爻 = 内部核心位置（臣位·内卦中）</span></span>
<span class="line"><span>  三爻 = 内外交界，危险位置</span></span>
<span class="line"><span>  四爻 = 外卦开始，近君之位</span></span>
<span class="line"><span>  五爻 = 君位，最重要的爻（九五之尊）</span></span>
<span class="line"><span>  上爻 = 事情终结，物极必反</span></span></code></pre></div><h3 id="_7-2-以乾卦为例-完整读法" tabindex="-1">7.2 以乾卦为例：完整读法 <a class="header-anchor" href="#_7-2-以乾卦为例-完整读法" aria-label="Permalink to &quot;7.2 以乾卦为例：完整读法&quot;">​</a></h3><p>【原典】《周易·乾卦》<br> 【卦辞】<strong>乾：元，亨，利，贞。</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>元 = 始，万物之始，大善之德</span></span>
<span class="line"><span>亨 = 通，亨通顺畅</span></span>
<span class="line"><span>利 = 宜，有利于行动</span></span>
<span class="line"><span>贞 = 正，坚守正道</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 乾卦的总体判断：</span></span>
<span class="line"><span>  这是一个充满创造力与生命力的情境，</span></span>
<span class="line"><span>  亨通顺畅，有利于行动，但必须坚守正道。</span></span></code></pre></div><p>【六爻爻辞节选】</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>初九：&quot;潜龙，勿用。&quot;</span></span>
<span class="line"><span>  = 龙潜于水，时机未到，不要轻举妄动。</span></span>
<span class="line"><span>  = 事情刚刚开始，积蓄能量，等待时机。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>九二：&quot;见龙在田，利见大人。&quot;</span></span>
<span class="line"><span>  = 龙出现在田野，适合拜见贵人。</span></span>
<span class="line"><span>  = 开始展现实力，寻求贵人支持。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>九三：&quot;君子终日乾乾，夕惕若厉，无咎。&quot;</span></span>
<span class="line"><span>  = 君子整日勤勉，夜晚仍保持警惕，虽危险但无过失。</span></span>
<span class="line"><span>  = 内外交界的危险位置，必须加倍谨慎。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>九四：&quot;或跃在渊，无咎。&quot;</span></span>
<span class="line"><span>  = 或跃起，或潜渊，随机应变，无过失。</span></span>
<span class="line"><span>  = 进入外卦，面临选择，保持灵活。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>九五：&quot;飞龙在天，利见大人。&quot;</span></span>
<span class="line"><span>  = 龙飞于天，适合拜见大人（或成为大人）。</span></span>
<span class="line"><span>  = 最佳状态，位正当中，是整卦最吉之爻。</span></span>
<span class="line"><span>  = &quot;九五之尊&quot;的来源。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>上九：&quot;亢龙有悔。&quot;</span></span>
<span class="line"><span>  = 龙飞得太高，必有悔恨。</span></span>
<span class="line"><span>  = 物极必反，盛极而衰，知退为上。</span></span></code></pre></div><blockquote><p>这六爻，描述的是<strong>一个完整的生命周期</strong>：<br> 潜伏→出现→勤勉→选择→飞翔→过极。<br> 从&quot;潜龙勿用&quot;到&quot;亢龙有悔&quot;，<br> 是任何事物从起步到极盛到衰退的完整轨迹。</p></blockquote><h2 id="八、《周易》的三个基础层次-象·数·理" tabindex="-1">八、《周易》的三个基础层次：象·数·理 <a class="header-anchor" href="#八、《周易》的三个基础层次-象·数·理" aria-label="Permalink to &quot;八、《周易》的三个基础层次：象·数·理&quot;">​</a></h2><p>这是读《周易》必须建立的基本框架。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>象（Xiang）= 符号与图像</span></span>
<span class="line"><span>  六十四卦的卦象、爻象</span></span>
<span class="line"><span>  = 宇宙现象的符号化表达</span></span>
<span class="line"><span>  = 最直观，最古老的层次</span></span>
<span class="line"><span></span></span>
<span class="line"><span>数（Shu）= 数字与推算</span></span>
<span class="line"><span>  大衍之数、爻变、纳甲……</span></span>
<span class="line"><span>  = 用数字系统推演变化</span></span>
<span class="line"><span>  = 汉代象数易学的核心</span></span>
<span class="line"><span></span></span>
<span class="line"><span>理（Li）= 义理与哲学</span></span>
<span class="line"><span>  卦辞爻辞的哲学解读</span></span>
<span class="line"><span>  = 从符号中提炼人生智慧</span></span>
<span class="line"><span>  = 宋代义理易学（程颐·朱熹）的核心</span></span></code></pre></div><p>【原典】《周易·系辞上传》第十二章<br> 【原文】<strong>是故，易有太极，是生两仪，两仪生四象，四象生八卦，八卦定吉凶，吉凶生大业。</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>太极 → 两仪 → 四象 → 八卦 → 吉凶 → 大业</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 从宇宙本体（太极）</span></span>
<span class="line"><span>  到符号系统（八卦）</span></span>
<span class="line"><span>  到人事判断（吉凶）</span></span>
<span class="line"><span>  到人生成就（大业）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 《周易》的完整逻辑链：</span></span>
<span class="line"><span>  宇宙规律 → 符号表达 → 人事应用</span></span></code></pre></div><h2 id="九、《周易》不是止算命说明书——必要的澄清" tabindex="-1">九、《周易》不是止算命说明书——必要的澄清 <a class="header-anchor" href="#九、《周易》不是止算命说明书——必要的澄清" aria-label="Permalink to &quot;九、《周易》不是止算命说明书——必要的澄清&quot;">​</a></h2><p>【原典】《周易·系辞上传》第一章<br> 【原文】**天尊地卑，乾坤定矣。卑高以陈，贵贱位矣。<br> **<strong>动静有常，刚柔断矣……</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>《周易》原本的功能，至少包含三个层次：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>① 占筮工具（最早的功能）</span></span>
<span class="line"><span>  西周时期，《周易》首先是一部占卜用书。</span></span>
<span class="line"><span>  通过蓍草演算，得到卦象，参照卦辞爻辞判断吉凶。</span></span>
<span class="line"><span>  这是它最原始、最直接的用途。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 哲学文本（孔子之后）</span></span>
<span class="line"><span>  孔子及其后学，将《周易》提升为哲学经典。</span></span>
<span class="line"><span>  &quot;一阴一阳之谓道&quot;——</span></span>
<span class="line"><span>  《周易》从占卜工具，变成了宇宙哲学的载体。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 变化之学（最深层的理解）</span></span>
<span class="line"><span>  《周易》的核心，不是&quot;算出结果&quot;，</span></span>
<span class="line"><span>  而是&quot;理解变化的规律&quot;。</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  &quot;易&quot;字，本义即&quot;变化&quot;。</span></span>
<span class="line"><span>  《周易》告诉你的，不是命运是什么，</span></span>
<span class="line"><span>  而是变化如何发生，以及如何在变化中做出正确的选择。</span></span></code></pre></div><blockquote><p>朱伯崑《易学哲学史》（北京大学出版社，1986年）：<br> 《周易》经历了从卜筮之书到哲学经典的历史转变，这一转变的关键节点，是孔子及其后学对《易》的哲学化诠释。</p></blockquote><h2 id="十、形·意·神·象·数·理-东方思维的六层模型" tabindex="-1">十、形·意·神·象·数·理：东方思维的六层模型 <a class="header-anchor" href="#十、形·意·神·象·数·理-东方思维的六层模型" aria-label="Permalink to &quot;十、形·意·神·象·数·理：东方思维的六层模型&quot;">​</a></h2><h3 id="_1、从-象数理-到-形意神-为什么要多走这一步" tabindex="-1">1、从&quot;象数理&quot;到&quot;形意神&quot;：为什么要多走这一步？ <a class="header-anchor" href="#_1、从-象数理-到-形意神-为什么要多走这一步" aria-label="Permalink to &quot;1、从&quot;象数理&quot;到&quot;形意神&quot;：为什么要多走这一步？&quot;">​</a></h3><p>前两章讲了《周易》的三个层次：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>象（Xiàng）= 符号与图像</span></span>
<span class="line"><span>数（Shù）  = 数字与推算</span></span>
<span class="line"><span>理（Lǐ）   = 义理与哲学</span></span></code></pre></div><p>这三个层次，是《周易》<strong>从外到内</strong>的读法——<br> 从看得见的符号（象），<br> 到可以推算的规律（数），<br> 到可以言说的道理（理）。</p><p>但东方思维，尤其是古人撰写经典时所用的思维方式，<br> 并不止步于此。</p><blockquote><p>象数理，是<strong>工具层</strong>——用来观察、推演、表达。<br> 形意神，是<strong>本质层</strong>——用来归纳、表意、洞见根源。</p></blockquote><p>古人的思维路径，是一条<strong>从表象到本质的俯瞰之路</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>现象世界（可见）</span></span>
<span class="line"><span>    ↓ 归纳</span></span>
<span class="line"><span>  形（Form）    ← 万象的外在轮廓与分类</span></span>
<span class="line"><span>    ↓ 提炼</span></span>
<span class="line"><span>  意（Meaning） ← 形背后承载的意象与含义</span></span>
<span class="line"><span>    ↓ 洞见</span></span>
<span class="line"><span>  神（Essence） ← 意背后不可言说的本质与规律</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 从&quot;看见&quot;到&quot;理解&quot;到&quot;洞见&quot;</span></span>
<span class="line"><span>= 从&quot;现象&quot;到&quot;规律&quot;到&quot;本质&quot;</span></span>
<span class="line"><span>= 天人合一的俯瞰观</span></span></code></pre></div><h3 id="_2、六层模型的完整结构" tabindex="-1">2、六层模型的完整结构 <a class="header-anchor" href="#_2、六层模型的完整结构" aria-label="Permalink to &quot;2、六层模型的完整结构&quot;">​</a></h3><p>将&quot;形意神&quot;与&quot;象数理&quot;合并，<br> 得到东方思维的<strong>六层完整模型</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│              神（Shén）                  │  ← 本质层·不可言说的终极规律</span></span>
<span class="line"><span>│         天人合一·道·太极                │</span></span>
<span class="line"><span>├─────────────────────────────────────────┤</span></span>
<span class="line"><span>│              意（Yì）                    │  ← 意象层·承载含义的符号与隐喻</span></span>
<span class="line"><span>│         意象思维·卦象表意·文字意象      │</span></span>
<span class="line"><span>├─────────────────────────────────────────┤</span></span>
<span class="line"><span>│              形（Xíng）                  │  ← 归纳层·对现象的抽象分类</span></span>
<span class="line"><span>│         归纳·分类·建立基本范畴          │</span></span>
<span class="line"><span>├─────────────────────────────────────────┤</span></span>
<span class="line"><span>│              理（Lǐ）                    │  ← 义理层·可言说的道理与哲学</span></span>
<span class="line"><span>│         义理·逻辑·推论                  │</span></span>
<span class="line"><span>├─────────────────────────────────────────┤</span></span>
<span class="line"><span>│              数（Shù）                   │  ← 推算层·数字化的规律表达</span></span>
<span class="line"><span>│         大衍之数·爻变·纳甲              │</span></span>
<span class="line"><span>├─────────────────────────────────────────┤</span></span>
<span class="line"><span>│              象（Xiàng）                 │  ← 符号层·最直观的图像表达</span></span>
<span class="line"><span>│         卦象·爻象·八卦符号              │</span></span>
<span class="line"><span>└─────────────────────────────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>↑ 从下往上：由表及里，由具体到抽象，由现象到本质</span></span>
<span class="line"><span>↓ 从上往下：由本质落地，由道到器，由神到象</span></span></code></pre></div><h3 id="_3、形——归纳的艺术" tabindex="-1">3、形——归纳的艺术 <a class="header-anchor" href="#_3、形——归纳的艺术" aria-label="Permalink to &quot;3、形——归纳的艺术&quot;">​</a></h3><h3 id="_3-1-什么是-形" tabindex="-1">3.1 什么是&quot;形&quot;？ <a class="header-anchor" href="#_3-1-什么是-形" aria-label="Permalink to &quot;3.1 什么是&quot;形&quot;？&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>形，不是指事物的外形长相，</span></span>
<span class="line"><span>而是指：对现象进行归纳后，</span></span>
<span class="line"><span>         得到的&quot;基本类型&quot;。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 抽象分类的结果。</span></span>
<span class="line"><span>= 把无限的现象，归纳为有限的范畴。</span></span></code></pre></div><h3 id="_3-2-三角形的例子" tabindex="-1">3.2 三角形的例子 <a class="header-anchor" href="#_3-2-三角形的例子" aria-label="Permalink to &quot;3.2 三角形的例子&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>现实中的三角形：</span></span>
<span class="line"><span>  等边三角形、等腰三角形、</span></span>
<span class="line"><span>  直角三角形、钝角三角形、锐角三角形……</span></span>
<span class="line"><span>  形态无穷无尽。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;形&quot;的归纳：</span></span>
<span class="line"><span>  按角度本质分类 →</span></span>
<span class="line"><span>    直角三角形（含一个90°角）</span></span>
<span class="line"><span>    非直角三角形（锐角·钝角）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  按边长本质分类 →</span></span>
<span class="line"><span>    等边、等腰、不等边</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 无论多少种三角形，</span></span>
<span class="line"><span>  都可以用少数几个&quot;形&quot;的范畴来覆盖。</span></span>
<span class="line"><span>= 这就是&quot;形&quot;的思维：化繁为简，归纳本质类型。</span></span></code></pre></div><h3 id="_3-3-《周易》中的-形" tabindex="-1">3.3 《周易》中的&quot;形&quot; <a class="header-anchor" href="#_3-3-《周易》中的-形" aria-label="Permalink to &quot;3.3 《周易》中的&quot;形&quot;&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>《周易》对宇宙万象的&quot;形&quot;的归纳：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第一层归纳：阴·阳（两仪）</span></span>
<span class="line"><span>  = 所有现象，归纳为两种基本属性。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第二层归纳：四象</span></span>
<span class="line"><span>  = 老阳·少阳·少阴·老阴</span></span>
<span class="line"><span>  = 两种属性的动态组合，归纳为四种状态。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第三层归纳：八卦</span></span>
<span class="line"><span>  = 八种基本自然力量</span></span>
<span class="line"><span>  = 天·地·水·火·雷·风·山·泽</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第四层归纳：六十四卦</span></span>
<span class="line"><span>  = 六十四种基本情境</span></span>
<span class="line"><span>  = 宇宙所有基本情境的完整&quot;形&quot;的分类。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 《周易》本身，就是一部</span></span>
<span class="line"><span>  用&quot;形&quot;的思维对宇宙进行归纳的伟大工程。</span></span></code></pre></div><blockquote><p>【原典】《周易·系辞上传》第二章<br><strong>&quot;圣人设卦观象，系辞焉而明吉凶，<br> **** 刚柔相推而生变化。&quot;</strong><br> = 圣人设立卦象，是为了对现象进行归纳（形），<br> 并在归纳的基础上，揭示吉凶变化。</p></blockquote><h3 id="_4、意——表意的艺术" tabindex="-1">4、意——表意的艺术 <a class="header-anchor" href="#_4、意——表意的艺术" aria-label="Permalink to &quot;4、意——表意的艺术&quot;">​</a></h3><h3 id="_4-1-什么是-意" tabindex="-1">4.1 什么是&quot;意&quot;？ <a class="header-anchor" href="#_4-1-什么是-意" aria-label="Permalink to &quot;4.1 什么是&quot;意&quot;？&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>意，是&quot;形&quot;背后承载的含义与意象。</span></span>
<span class="line"><span>= 不是直接说出来的，而是&quot;寓于象中&quot;的。</span></span>
<span class="line"><span>= 意象思维：用具体的形象，承载抽象的含义。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>中文&quot;意象&quot;二字，本身就是这个思维的体现：</span></span>
<span class="line"><span>  意 = 含义（抽象）</span></span>
<span class="line"><span>  象 = 图像（具体）</span></span>
<span class="line"><span>  意象 = 用具体图像承载抽象含义。</span></span></code></pre></div><h3 id="_4-2-意象思维的特点" tabindex="-1">4.2 意象思维的特点 <a class="header-anchor" href="#_4-2-意象思维的特点" aria-label="Permalink to &quot;4.2 意象思维的特点&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>西方思维路径：</span></span>
<span class="line"><span>  抽象概念 → 定义 → 逻辑推论</span></span>
<span class="line"><span>  （直接说出来）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>东方意象思维路径：</span></span>
<span class="line"><span>  具体形象 → 意象 → 感悟含义</span></span>
<span class="line"><span>  （让你自己悟出来）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>例：</span></span>
<span class="line"><span>  &quot;亢龙有悔&quot;（乾卦上九爻辞）</span></span>
<span class="line"><span>  不说&quot;物极必反，盛极而衰&quot;，</span></span>
<span class="line"><span>  而是用&quot;龙飞得太高，必有悔恨&quot;这个意象，</span></span>
<span class="line"><span>  让读者自己感受到那个道理。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  &quot;潜龙勿用&quot;（乾卦初九爻辞）</span></span>
<span class="line"><span>  不说&quot;时机未到，不宜行动&quot;，</span></span>
<span class="line"><span>  而是用&quot;龙潜于水&quot;这个意象，</span></span>
<span class="line"><span>  让读者感受到那种蓄势待发的状态。</span></span></code></pre></div><h3 id="_4-3-《周易》中的-意" tabindex="-1">4.3 《周易》中的&quot;意&quot; <a class="header-anchor" href="#_4-3-《周易》中的-意" aria-label="Permalink to &quot;4.3 《周易》中的&quot;意&quot;&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>《周易》的卦名，几乎全部是意象：</span></span>
<span class="line"><span>  屯 = 草木破土而出，艰难初生之象</span></span>
<span class="line"><span>  蒙 = 山下有泉，蒙昧待启之象</span></span>
<span class="line"><span>  需 = 云在天上，等待时机之象</span></span>
<span class="line"><span>  讼 = 水与天相背，争讼对立之象</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每一个卦名，都是一个意象，</span></span>
<span class="line"><span>每一个意象，都承载着一套含义。</span></span>
<span class="line"><span>读懂意象，才能读懂卦。</span></span></code></pre></div><blockquote><p>【原典】《周易·系辞下传》第二章<br><strong>&quot;古者包牺氏之王天下也，<br> **** 仰则观象于天，俯则观法于地……<br> **** 近取诸身，远取诸物，<br> **** 于是始作八卦，以通神明之德，<br> **** 以类万物之情。&quot;</strong><br> = 八卦的创立，本身就是意象思维的产物：<br> 观天地万物之象（形），<br> 提炼其意（意），<br> 以通神明（神）。</p></blockquote><h3 id="_5、神——洞见的艺术" tabindex="-1">5、神——洞见的艺术 <a class="header-anchor" href="#_5、神——洞见的艺术" aria-label="Permalink to &quot;5、神——洞见的艺术&quot;">​</a></h3><h3 id="_5-1-什么是-神" tabindex="-1">5.1 什么是&quot;神&quot;？ <a class="header-anchor" href="#_5-1-什么是-神" aria-label="Permalink to &quot;5.1 什么是&quot;神&quot;？&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>神，不是神灵，不是神秘，</span></span>
<span class="line"><span>而是：透过形与意，洞见的那个</span></span>
<span class="line"><span>       &quot;不可言说的终极规律&quot;。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 老子所说的&quot;道&quot;。</span></span>
<span class="line"><span>= 《周易》所说的&quot;太极&quot;。</span></span>
<span class="line"><span>= 不能被完全定义，只能被感悟。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;神&quot;的特点：</span></span>
<span class="line"><span>  ① 不可被完全言说（&quot;道可道，非常道&quot;）</span></span>
<span class="line"><span>  ② 可以被感悟与体验</span></span>
<span class="line"><span>  ③ 是形与意的最终归宿</span></span>
<span class="line"><span>  ④ 是天人合一的那个&quot;合一点&quot;</span></span></code></pre></div><h3 id="_5-2-神-与天人合一" tabindex="-1">5.2 &quot;神&quot;与天人合一 <a class="header-anchor" href="#_5-2-神-与天人合一" aria-label="Permalink to &quot;5.2 &quot;神&quot;与天人合一&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天人合一，不是一句空话，</span></span>
<span class="line"><span>它是&quot;神&quot;这个层次的具体体现：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  天（宇宙规律）</span></span>
<span class="line"><span>  ↕ 合一</span></span>
<span class="line"><span>  人（人的认知与行为）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 当人的认知（形·意）</span></span>
<span class="line"><span>  深入到宇宙的本质规律（神）时，</span></span>
<span class="line"><span>  天与人之间的隔阂消失——</span></span>
<span class="line"><span>  这就是天人合一。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>《周易》的终极目标，不是算卦，</span></span>
<span class="line"><span>而是让人通过象·数·理·形·意，</span></span>
<span class="line"><span>最终洞见那个&quot;神&quot;——</span></span>
<span class="line"><span>即宇宙变化的终极规律，</span></span>
<span class="line"><span>并与之合一，做出顺应规律的选择。</span></span></code></pre></div><h3 id="_5-3-神-在《周易》中的体现" tabindex="-1">5.3 &quot;神&quot;在《周易》中的体现 <a class="header-anchor" href="#_5-3-神-在《周易》中的体现" aria-label="Permalink to &quot;5.3 &quot;神&quot;在《周易》中的体现&quot;">​</a></h3><blockquote><p>【原典】《周易·系辞上传》第五章<br><strong>一阴一阳之谓道，继之者善也，成之者性也。</strong></p></blockquote><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;一阴一阳之谓道&quot;——</span></span>
<span class="line"><span>  这句话，是《周易》对&quot;神&quot;的最接近的表达：</span></span>
<span class="line"><span>  阴阳的交替变化，就是道，就是神，</span></span>
<span class="line"><span>  就是宇宙的终极规律。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  但注意：这句话说的是&quot;之谓道&quot;，</span></span>
<span class="line"><span>  = 阴阳只是道的&quot;表达方式&quot;，</span></span>
<span class="line"><span>    不是道本身。</span></span>
<span class="line"><span>  道（神）本身，依然不可被完全言说。</span></span></code></pre></div><blockquote><p>【原典】《周易·系辞上传》第十章<br> **《易》无思也，无为也，寂然不动，感而遂通天下之故，<br> **<strong>非天下之至神，其孰能与于此？&quot;</strong></p></blockquote><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;寂然不动，感而遂通&quot;——</span></span>
<span class="line"><span>  这正是&quot;神&quot;的状态：</span></span>
<span class="line"><span>  不是主动推算，而是静默感应，</span></span>
<span class="line"><span>  与宇宙规律直接相通。</span></span>
<span class="line"><span>  = 象数理是路径，神是目的地。</span></span></code></pre></div><h3 id="_6、六层模型在《周易》中的完整对应" tabindex="-1">6、六层模型在《周易》中的完整对应 <a class="header-anchor" href="#_6、六层模型在《周易》中的完整对应" aria-label="Permalink to &quot;6、六层模型在《周易》中的完整对应&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>神  ←→  太极·道·一阴一阳之谓道</span></span>
<span class="line"><span>         = 不可言说的终极规律</span></span>
<span class="line"><span></span></span>
<span class="line"><span>意  ←→  卦名·卦象·意象表达</span></span>
<span class="line"><span>         = 用具体形象承载抽象含义</span></span>
<span class="line"><span></span></span>
<span class="line"><span>形  ←→  阴阳·四象·八卦·六十四卦</span></span>
<span class="line"><span>         = 对宇宙现象的归纳分类</span></span>
<span class="line"><span></span></span>
<span class="line"><span>理  ←→  卦辞·爻辞·十翼的哲学阐释</span></span>
<span class="line"><span>         = 可言说的道理与义理</span></span>
<span class="line"><span></span></span>
<span class="line"><span>数  ←→  大衍之数·爻变·纳甲·八宫</span></span>
<span class="line"><span>         = 数字化的规律推演</span></span>
<span class="line"><span></span></span>
<span class="line"><span>象  ←→  六十四卦符号·爻象·卦图</span></span>
<span class="line"><span>         = 最直观的视觉符号</span></span></code></pre></div><h3 id="七、这个模型如何用于读书与写作" tabindex="-1">七、这个模型如何用于读书与写作？ <a class="header-anchor" href="#七、这个模型如何用于读书与写作" aria-label="Permalink to &quot;七、这个模型如何用于读书与写作？&quot;">​</a></h3><p>这个六层模型，不只是读《周易》的工具，<br> 它是古人<strong>撰写一切经典时</strong>所用的思维框架。</p><h3 id="_7-1-古人写作的思维路径-从上到下" tabindex="-1">7.1 古人写作的思维路径（从上到下） <a class="header-anchor" href="#_7-1-古人写作的思维路径-从上到下" aria-label="Permalink to &quot;7.1 古人写作的思维路径（从上到下）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>神（洞见本质）</span></span>
<span class="line"><span>  ↓ 转化为</span></span>
<span class="line"><span>意（选择意象）</span></span>
<span class="line"><span>  ↓ 落实为</span></span>
<span class="line"><span>形（建立分类）</span></span>
<span class="line"><span>  ↓ 表达为</span></span>
<span class="line"><span>理（阐述道理）</span></span>
<span class="line"><span>  ↓ 辅助以</span></span>
<span class="line"><span>数（数字佐证）</span></span>
<span class="line"><span>  ↓ 呈现为</span></span>
<span class="line"><span>象（符号图像）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 古人先洞见本质（神），</span></span>
<span class="line"><span>  再选择意象（意），</span></span>
<span class="line"><span>  再建立分类（形），</span></span>
<span class="line"><span>  最后才落笔成文（理·数·象）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 我们看到的经典文字，</span></span>
<span class="line"><span>  是&quot;从上往下&quot;落地的结果；</span></span>
<span class="line"><span>  我们读经典，</span></span>
<span class="line"><span>  则是&quot;从下往上&quot;溯源的过程。</span></span></code></pre></div><h3 id="_7-2-读者阅读的思维路径-从下到上" tabindex="-1">7.2 读者阅读的思维路径（从下到上） <a class="header-anchor" href="#_7-2-读者阅读的思维路径-从下到上" aria-label="Permalink to &quot;7.2 读者阅读的思维路径（从下到上）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>象（看到符号与文字）</span></span>
<span class="line"><span>  ↓ 理解</span></span>
<span class="line"><span>数（感受数字规律）</span></span>
<span class="line"><span>  ↓ 推论</span></span>
<span class="line"><span>理（领会道理）</span></span>
<span class="line"><span>  ↓ 归纳</span></span>
<span class="line"><span>形（建立分类认知）</span></span>
<span class="line"><span>  ↓ 感悟</span></span>
<span class="line"><span>意（体会意象含义）</span></span>
<span class="line"><span>  ↓ 洞见</span></span>
<span class="line"><span>神（触及本质规律）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 读书，是一个从象到神的溯源之旅。</span></span>
<span class="line"><span>= 读懂了&quot;神&quot;，才算真正读懂了一本书。</span></span></code></pre></div><h3 id="_7-3-实例-用六层模型读乾卦" tabindex="-1">7.3 实例：用六层模型读乾卦 <a class="header-anchor" href="#_7-3-实例-用六层模型读乾卦" aria-label="Permalink to &quot;7.3 实例：用六层模型读乾卦&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>象：☰☰ 六条阳爻，纯阳之卦。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>数：六爻全阳，2⁶最大值，阳能量的极致表达。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>理：元亨利贞，创始·亨通·有利·守正，</span></span>
<span class="line"><span>    是最完整的生命周期描述。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>形：乾代表&quot;纯阳&quot;这一基本类型，</span></span>
<span class="line"><span>    是六十四卦中阳能量的极致归纳。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>意：六条龙的意象——</span></span>
<span class="line"><span>    潜龙·见龙·乾乾·跃渊·飞龙·亢龙，</span></span>
<span class="line"><span>    是一切生命从潜伏到极盛到衰退的意象表达。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>神：乾卦的&quot;神&quot;，是&quot;刚健自强&quot;的宇宙本质——</span></span>
<span class="line"><span>    《象传》曰：&quot;天行健，君子以自强不息。&quot;</span></span>
<span class="line"><span>    这不是一条建议，而是宇宙规律的洞见：</span></span>
<span class="line"><span>    天道永远运行不息，这是神；</span></span>
<span class="line"><span>    君子效法天道，这是天人合一。</span></span></code></pre></div><h3 id="_8、本章小结" tabindex="-1">8、本章小结 <a class="header-anchor" href="#_8、本章小结" aria-label="Permalink to &quot;8、本章小结&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>象数理，是《周易》给我们的工具：</span></span>
<span class="line"><span>  用来观察（象）、推演（数）、理解（理）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>形意神，是东方思维给我们的方向：</span></span>
<span class="line"><span>  用来归纳（形）、表意（意）、洞见（神）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>六层合一，是古人撰写经典时的完整思维框架：</span></span>
<span class="line"><span>  从神到象，是写作（由本质落地为符号）；</span></span>
<span class="line"><span>  从象到神，是阅读（由符号溯源到本质）。</span></span></code></pre></div><h2 id="十、本章小结" tabindex="-1">十、本章小结 <a class="header-anchor" href="#十、本章小结" aria-label="Permalink to &quot;十、本章小结&quot;">​</a></h2><p>六十四卦，说了一件事，但这件事很具体：</p><blockquote><p>**宇宙的64种基本情境，每一种都有其内在逻辑、<br> **<strong>发展轨迹与应对之道。</strong></p></blockquote><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 不是神秘，是分类</span></span>
<span class="line"><span>   64卦 = 用二分法对宇宙情境的穷举分类。</span></span>
<span class="line"><span>   不神秘，是逻辑。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 不是宿命，是变化</span></span>
<span class="line"><span>   每一卦都有六爻，每一爻都在变化。</span></span>
<span class="line"><span>   《周易》的核心字，就是&quot;易&quot;——变化。</span></span>
<span class="line"><span>   它告诉你的，永远是&quot;此刻如何&quot;，不是&quot;永远如此&quot;。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 不是答案，是框架</span></span>
<span class="line"><span>   卦辞爻辞给的，不是&quot;你会怎样&quot;，</span></span>
<span class="line"><span>   而是&quot;这种情境下，通常的规律是什么&quot;。</span></span>
<span class="line"><span>   用框架思考，不用框架代替思考。</span></span></code></pre></div><p>象数理，是《周易》给我们的工具：</p><p>用来观察（象）、推演（数）、理解（理）。</p><p>形意神，是东方思维给我们的方向：</p><p>用来归纳（形）、表意（意）、洞见（神）。</p><p>六层合一，是古人撰写经典时的完整思维框架：</p><p>从神到象，是写作（由本质落地为符号）；</p><p>从象到神，是阅读（由符号溯源到本质）。</p><p>《周易》六十四卦，可能是人类历史上最早的、最系统的<strong>情境分类学（个人观点）</strong>。</p><p>这也是为什么，《周易》读了三千年，每个时代的人都能从中读出新的东西——</p><p>因为它的&quot;象&quot;是固定的，但它指向的&quot;神&quot;是开放的。</p><p>每一个读者，都在用自己时代的&quot;形&quot;与&quot;意&quot;，去触碰那个永恒的&quot;神&quot;。</p><p>这，就是经典的生命力所在。</p><hr><h2 id="附录-引用索引" tabindex="-1">附录：引用索引 <a class="header-anchor" href="#附录-引用索引" aria-label="Permalink to &quot;附录：引用索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">引用内容</th><th style="text-align:left;">原典／来源</th><th style="text-align:left;">时代／年份</th></tr></thead><tbody><tr><td style="text-align:left;">&quot;因而重之，爻在其中矣&quot;</td><td style="text-align:left;">《周易·系辞下传》第二章</td><td style="text-align:left;">战国至西汉</td></tr><tr><td style="text-align:left;">&quot;昔西伯拘羑里，演《周易》&quot;</td><td style="text-align:left;">《史记·太史公自序》</td><td style="text-align:left;">西汉·司马迁</td></tr><tr><td style="text-align:left;">&quot;文王以诸侯顺命……作上下篇&quot;</td><td style="text-align:left;">《汉书·艺文志》</td><td style="text-align:left;">东汉·班固</td></tr><tr><td style="text-align:left;">&quot;孔子晚而喜《易》……韦编三绝&quot;</td><td style="text-align:left;">《史记·孔子世家》</td><td style="text-align:left;">西汉·司马迁</td></tr><tr><td style="text-align:left;">乾卦卦辞·爻辞</td><td style="text-align:left;">《周易·乾卦》</td><td style="text-align:left;">西周初期</td></tr><tr><td style="text-align:left;">&quot;有天地，然后万物生焉……&quot;</td><td style="text-align:left;">《周易·序卦传》</td><td style="text-align:left;">战国至西汉</td></tr><tr><td style="text-align:left;">&quot;天尊地卑，乾坤定矣……&quot;</td><td style="text-align:left;">《周易·系辞上传》第一章</td><td style="text-align:left;">战国至西汉</td></tr><tr><td style="text-align:left;">&quot;易有太极，是生两仪……&quot;</td><td style="text-align:left;">《周易·系辞上传》第十二章</td><td style="text-align:left;">战国至西汉</td></tr><tr><td style="text-align:left;">六十四卦符号体系早于文王的考古证据</td><td style="text-align:left;">梁韦弦《关于数字卦与六十四卦符号体系之形成问题》</td><td style="text-align:left;">《周易研究》，2007年</td></tr><tr><td style="text-align:left;">八卦到六十四卦的思维逻辑</td><td style="text-align:left;">史宁中《从八卦到六十四卦：试论〈周易〉的思维逻辑》</td><td style="text-align:left;">《哲学研究》，2011年</td></tr><tr><td style="text-align:left;">错综关系与六十四卦结构</td><td style="text-align:left;">向世陵《&quot;重&quot;&quot;错&quot;之义与六十四卦的生成》</td><td style="text-align:left;">《周易研究》，2001年</td></tr><tr><td style="text-align:left;">卦辞爻辞作者考辨</td><td style="text-align:left;">黄寿祺、张善文《周易译注》</td><td style="text-align:left;">上海古籍出版社，1989年</td></tr><tr><td style="text-align:left;">《易》来源问题考辨</td><td style="text-align:left;">谢金良《本世纪〈易经〉来源问题研究的若干考辨》</td><td style="text-align:left;">《福建论坛》，1998年</td></tr><tr><td style="text-align:left;">《周易》从卜筮到哲学的转变</td><td style="text-align:left;">朱伯崑《易学哲学史》</td><td style="text-align:left;">北京大学出版社，1986年</td></tr><tr><td style="text-align:left;">卦辞写定时间与作者</td><td style="text-align:left;">廖名春《周易经传与易学史新论》</td><td style="text-align:left;">齐鲁书社，2001年</td></tr></tbody></table><hr><p><em>文档版本：v1.0 · 六十四卦基础 ｜ 2026年7月 ｜ 持续更新中</em></p>`,251)])])}const g=n(e,[["render",t]]);export{r as __pageData,g as default};
